<?php require_once 'config.php';$uid=require_user();$q=$conn->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$q->bind_param('i',$uid);$q->execute();$orders=$q->get_result()->fetch_all(MYSQLI_ASSOC);?>
<!doctype html><html lang="uk"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Мої замовлення — flora.atelier</title><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/flor-v5.css"><link rel="stylesheet" href="css/flor-v6.css"><link rel="stylesheet" href="css/flor-v7.css"><link rel="stylesheet" href="css/flor-v8.css"><link rel="stylesheet" href="css/flor-v9.css"></head><body><?php require 'header.php';?><main class="page-shell"><div class="page-intro"><span class="eyebrow">МОЯ КВІТКОВА ІСТОРІЯ</span><h1>Мої <em>замовлення</em></h1></div><div class="order-history"><?php if(!$orders):?><div class="empty-state">Твої замовлення ще попереду. <a href="shop.php" class="link-underline">Обрати букет ↗</a></div><?php endif;foreach($orders as $o):?><article class="history-card"><div class="history-top"><h3>Замовлення №<?=(int)$o['id']?></h3><span class="order-chip <?=e($o['payment_status'])?>"><?=e(['pending'=>'Очікує','completed'=>'Завершено','cancelled'=>'Скасовано'][$o['payment_status']]??$o['payment_status'])?></span></div><small><?=e($o['placed_on'])?></small><p><?=e($o['total_products'])?></p><span><?=e($o['address'])?></span><strong><?=money($o['total_price'])?></strong></article><?php endforeach;?></div></main><?php require 'footer.php';?></body></html>
